def transform(grid):
    h=[r[:] for r in grid]
    H,W=len(grid),len(grid[0]); starts=[0,6,12]
    masks=[]
    for rs in starts:
      for cs in starts:
        masks.append([(r-rs,c-cs) for r in range(rs,min(rs+5,H)) for c in range(cs,min(cs+5,W)) if grid[r][c]==9])
    for rs in starts:
      for cs in starts:
        for mask in masks:
          for dr,dc in mask:
            r,c=rs+dr,cs+dc
            if h[r][c]==0:h[r][c]=7
    return h
